<?php
declare(strict_types=1);
require_once __DIR__ . '/db.php';require_once __DIR__ . '/rss_display_balance.php';
function rss_trade_enrich_items(array $items): array{$ids=[];foreach($items as $i){if(is_array($i)&&($s=(int)($i['source_id']??0))>0)$ids[$s]=true;}if($ids===[])return $items;$meta=[];try{$ks=array_keys($ids);$ph=implode(',',array_fill(0,count($ks),'?'));$st=db()->prepare('SELECT rs.id AS source_id,pr.partner_site_id,ps.ref_code,ps.url AS partner_site_url FROM rss_sources rs LEFT JOIN partner_rss pr ON pr.id=rs.source_ref_id LEFT JOIN partner_sites ps ON ps.id=pr.partner_site_id WHERE rs.id IN ('.$ph.')');$st->execute($ks);foreach($st->fetchAll(PDO::FETCH_ASSOC)?:[] as $r){$s=(int)($r['source_id']??0);if($s>0)$meta[$s]=['partner_site_id'=>(int)($r['partner_site_id']??0),'partner_ref_code'=>trim((string)($r['ref_code']??'')),'partner_site_url'=>trim((string)($r['partner_site_url']??''))];}}catch(Throwable $e){error_log('[rss] access-trade metadata lookup failed: '.$e->getMessage());return $items;}foreach($items as &$i){if(!is_array($i))continue;$m=$meta[(int)($i['source_id']??0)]??null;if(is_array($m))$i=array_merge($i,$m);}unset($i);return $items;}
function rss_trade_weight(int $inCount,int $outCount): float{$inCount=max(0,$inCount);$outCount=max(0,$outCount);if($inCount===0&&$outCount===0)return .5;$debt=max(0,$inCount-$outCount);if($debt>0)return min(120.0,1.0+(float)$debt+min(10.0,sqrt((float)$inCount)/2.0));return max(.15,.5/(1.0+(max(0,$outCount-$inCount)/10.0)));}
function rss_trade_split_columns(array $items): array{$l=[];$r=[];$ll=null;$lr=null;foreach($items as $i){if(!is_array($i))continue;$k=rss_partner_display_source_key($i);$lc=count($l);$rc=count($r);if($lc<$rc)$t='l';elseif($rc<$lc)$t='r';else{$a=$k!==''&&$k===$ll;$b=$k!==''&&$k===$lr;if($a&&!$b)$t='r';elseif($b&&!$a)$t='l';else$t=random_int(0,1)===0?'l':'r';}if($t==='l'){$l[]=$i;$ll=$k;}else{$r[]=$i;$lr=$k;}}return[$l,$r];}
function rss_trade_out_url(array $item): string{$target=trim((string)($item['link']??''));$pid=(int)($item['partner_site_id']??0);$ref=trim((string)($item['partner_ref_code']??''));if($target===''||$pid<=0||$ref==='')return $target;$q=http_build_query(['partner'=>$pid,'ref'=>$ref,'to'=>$target]);return function_exists('public_url')?public_url('out.php?'.$q):'/out.php?'.$q;}
